    override fun sequenceBegin(id: Int) {
        if (sp == stk.size) stk = stk.copyOf(sp * 2)
        stk[sp++] = cur
        when (cur) {
            0 -> when (id) {
                15 -> { m.e_rows.clear(); cur = 1 }
                16 -> { m.b_rows.clear(); cur = 2 }
                17 -> { m.e_cube.clear(); cur = 3 }
                18 -> cur = 5
                19 -> cur = 6
                20 -> { m.holders.clear(); cur = 7 }
                21 -> cur = 9
                22 -> cur = 10
                23 -> cur = 11
                24 -> cur = 12
                25 -> { m.u_list.clear(); cur = 13 }
                28 -> { m.b_cube.clear(); cur = 15 }
                29 -> cur = 17
                30 -> { m.u_blist.clear(); cur = 19 }
                else -> cur = DEAD
            }
            3 -> { Seq.reserveRowList(m.e_cube, id, 2, MAX_DYN_ARRAY_COUNT); _ex_Root_e__cube = id; cur = 4 }
            5 -> cur = DEAD
            6 -> cur = DEAD
            7 -> { Seq.reserveElem(m.holders, id, 2, MAX_DYN_ARRAY_COUNT) { Holder() }; _ex_Root_holders = id; cur = 8 }
            8 -> cur = DEAD
            9 -> cur = DEAD
            10 -> cur = DEAD
            11 -> cur = DEAD
            12 -> cur = DEAD
            13 -> { Seq.reserveElem(m.u_list, id, 2, MAX_DYN_ARRAY_COUNT) { Choice__DefaultShort() }; _ex_Root_u__list = id; cur = 14 }
            14 -> cur = DEAD
            15 -> { Seq.reserveRowList(m.b_cube, id, 2, MAX_DYN_ARRAY_COUNT); _ex_Root_b__cube = id; cur = 16 }
            17 -> when (id) {
                0 -> cur = 18
                else -> cur = DEAD
            }
            18 -> cur = DEAD
            19 -> { Seq.reserveElem(m.u_blist, id, 2, MAX_DYN_ARRAY_COUNT) { Choice__DefaultFlags() }; _ex_Root_u__blist = id; cur = 20 }
            20 -> cur = DEAD
            else -> cur = DEAD
        }
    }

    override fun sequenceEnd() {
        cur = if (sp > 0) stk[--sp] else 0
    }
